export const ENEMY_GLOBAL = { hp: 0.58, dmg: 0.30, armor: 0.85 };
export const ACT_MULT = { 0: [0.5, 0.75], 1: [0.85, 0.92], 2: [1.15, 1.1], 3: [1.85, 1.3], 4: [2.15, 1.45], 5: [2.45, 1.6], 6: [2.6, 1.65], 7: [3.2, 1.78], 8: [3.9, 1.9], 9: [4.7, 2.0], 10: [5.6, 2.1] };
